523: 
524: 	if (((dev->flags & IFF_POINTOPOINT) && !p.iph.daddr) ||
525: 	    (!(dev->flags & IFF_POINTOPOINT) && p.iph.daddr))
526: 		return -EINVAL;
527: 
528: 	return ip_tunnel_changelink(dev, tb, &p, fwmark);
529: }

